# Zero-component enclosure (4-conn zeros), no barrier idea: component enclosed iff doesn't touch border
seen=set(); comps=[]
for i in range(h):
    for j in range(w):
        if I[i][j]==0 and (i,j) not in seen:
            dq=deque([(i,j)]); comp={(i,j)}; seen.add((i,j))
            while dq:
                a,b=dq.popleft()
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    p,q=a+da,b+db
                    if 0<=p<h and 0<=q<w and I[p][q]==0 and (p,q) not in seen:
                        seen.add((p,q)); comp.add((p,q)); dq.append((p,q))
            comps.append(comp)
enc=[c for c in comps if not ((min(i for i,_ in c)==0) or (max(i for i,_ in c)==h-1) or (min(j for _,j in c)==0) or (max(j for _,j in c)==w-1))]
print('enclosed zero comps:',[(len(c),min(i for i,_ in c),max(i for i,_ in c),min(j for _,j in c),max(j for _,j in c)) for c in enc])
chz=[(i,j) for i,j,a,b in [(a,b,O[a][b]) for a in range(h) for b in range(w) if I[a][b]==0 and O[a][b]!=I[a][b]]]
print('changed zeros n=',len(chz),'enclosed comps total cells=',sum(len(c) for c in enc))
# which enclosed comp do changed zeros belong to?
for c in enc: print(sorted(c)[:8],'...' if len(c)>8 else '', 'Ocolors:',sorted(set(O[a][b] for a,b in c)))
